'use strict';

const { hasOwn } = require('../../../utils/safe-object');

module.exports = (role) => {
  if (typeof role === 'string') {
    // role is a statically defined iam arn
    if (role.startsWith('arn:')) return { roleArn: role };
    // role is the default role generated by osls
    if (role === 'IamRoleLambdaExecution') return { roleArn: { 'Fn::GetAtt': [role, 'Arn'] } };
    // role is a Logical Role Name
    return { roleArn: { 'Fn::GetAtt': [role, 'Arn'] }, dependsOn: role };
  }
  // role is an "Fn::GetAtt" object
  if (hasOwn(role, 'Fn::GetAtt')) return { roleArn: role, dependsOn: role['Fn::GetAtt'][0] };
  // role is an "Fn::ImportValue" or "Fn::Sub" object
  return { roleArn: role };
};
